			body: fmt.Sprintf(`{"update_id":7306,"message":{"message_id":12,"from":{"id":1087968824},"sender_chat":{"id":-100100,"type":"supergroup"},"chat":{"id":-42,"type":"group"},"text":"%s"}}`, operation.Challenge),
