			if err != nil {
				t.Fatal(err)
			}
		}
		validBody := []byte(fmt.Sprintf(`{"update_id":%d,"message":{"message_id":%d,"from":{"id":41,"first_name":"Operator"},"chat":{"id":%d,"type":%q},"text":%q}}`, 7310+index, 16+index, claim.conversation, claim.chatKind, operation.Challenge))
